class TestConcurrencySafety:
    """Verify package components are safe for concurrent use."""

    def test_singleton_patterns(self):
        """Check that managers don't create unexpected state per import."""
        from swarm_security.auth import AuthManager as AuthManager1
        from swarm_security.auth import AuthManager as AuthManager2
        # They should be the same class (not necessarily same instance)
        assert AuthManager1 is AuthManager2, (
            "AuthManager class identity changed between imports"
        )

    def test_thread_safe_exceptions(self):
        """Exception classes should be thread-safe (no mutable class vars)."""
        for exc_class in [ValidationError, AuthenticationError, AuditError, RateLimitExceeded]:
            exc = exc_class("test")
            assert str(exc) == "test", (
                f"{exc_class.__name__} message not preserved: '{exc}'"
            )
            # Ensure no shared mutable state
            exc2 = exc_class("another")
            assert str(exc2) == "another", (
                f"{exc_class.__name__} instances share state"
            )


